def investigate(context, acquire):
    hist = acquire("history")
    # Family: put is one of IGNORE, REPLACE, UPSERT(value).
    # Instrumentation: none or one AFTER INSERT trigger logging one row.
    # Channel: main changes(), main total_changes, or main+other total_changes.
    # We must determine which combination is consistent with all receipts,
    # then predict the goal for the query sequence.

    # We cannot actually run SQLite. We simulate the family members and keep
    # only those consistent with every calibration receipt. If all survivors
    # agree on the goal, return that value; otherwise unresolved.

    def simulate(put_mode, trigger, channel_mode, actions):
        # Returns (channel_value, committed_count, committed_sum) or None if
        # the action sequence is invalid for this family member.
        # State: committed items dict, per-connection open transaction state.
        # We model main and other connections.
        committed = {}
        # pending changes per connection: dict of key->value or None for delete
        # We track transaction state per connection.
        tx = {"main": None, "other": None}
        # total_changes counters per connection (cumulative, including rolled back)
        total = {"main": 0, "other": 0}
        # changes() is last direct row-change count on main connection
        last_changes = 0
        # log rows inserted by trigger (count only matters for channel? no,
        # trigger affects changes()/total_changes because it inserts a row)
        # Actually AFTER INSERT trigger inserts one row into log; that insert
        # is a direct row change on the same connection, so it increments
        # changes() and total_changes for that connection.

        def apply_write(conn, key, value, is_delete):
            nonlocal last_changes
            # Determine effect on the items table for this connection.
            # We need to know current visible state for this connection:
            # committed plus its own pending changes.
            base = dict(committed)
            if tx[conn] is not None:
                base.update(tx[conn])
            # base maps key->value; deleted keys removed
            # Actually tx[conn] stores pending ops; we can maintain a working
            # dict for the transaction.
            # Simpler: maintain per-connection working state.
            return None

        # We'll maintain per-connection working dicts.
        work = {"main": dict(committed), "other": dict(committed)}
        # But committed changes when a transaction commits on one connection
        # should be visible to the other connection only after commit.
        # We'll handle by updating committed on commit and refreshing the
        # other connection's work if it has no open transaction.

        # Re-initialize properly:
        committed = {}
        work = {"main": {}, "other": {}}
        tx = {"main": False, "other": False}
        total = {"main": 0, "other": 0}
        last_changes = 0

        def refresh(conn):
            if not tx[conn]:
                work[conn] = dict(committed)

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if conn not in ("main", "other"):
                return None
            if op == "begin":
                if tx[conn]:
                    return None
                tx[conn] = True
                work[conn] = dict(committed)
            elif op == "commit":
                if not tx[conn]:
                    return None
                committed = dict(work[conn])
                tx[conn] = False
                # other connection sees new committed state if not in tx
                other = "other" if conn == "main" else "main"
                if not tx[other]:
                    work[other] = dict(committed)
            elif op == "rollback":
                if not tx[conn]:
                    return None
                tx[conn] = False
                work[conn] = dict(committed)
            elif op in ("put", "update", "delete"):
                key = act.get("key")
                if not isinstance(key, str) or not key:
                    return None
                if op == "delete":
                    if key in work[conn]:
                        del work[conn][key]
                        total[conn] += 1
                        if conn == "main":
                            last_changes = 1
                        # trigger only on insert, not delete
                    else:
                        total[conn] += 0
                        if conn == "main":
                            last_changes = 0
                else:
                    value = act.get("value")
                    if not isinstance(value, int) or value < 0 or value > 1000000:
                        return None
                    existed = key in work[conn]
                    if op == "put":
                        if put_mode == "ignore":
                            if existed:
                                # no change
                                if conn == "main":
                                    last_changes = 0
                                continue
                            work[conn][key] = value
                            total[conn] += 1
                            if conn == "main":
                                last_changes = 1
                            if trigger:
                                total[conn] += 1
                                if conn == "main":
                                    last_changes += 1
                        elif put_mode == "replace":
                            work[conn][key] = value
                            total[conn] += 1
                            if conn == "main":
                                last_changes = 1
                            if trigger:
                                total[conn] += 1
                                if conn == "main":
                                    last_changes += 1
                        elif put_mode == "upsert":
                            if existed:
                                work[conn][key] = value
                                total[conn] += 1
                                if conn == "main":
                                    last_changes = 1
                                # ON CONFLICT DO UPDATE does not fire AFTER INSERT
                            else:
                                work[conn][key] = value
                                total[conn] += 1
                                if conn == "main":
                                    last_changes = 1
                                if trigger:
                                    total[conn] += 1
                                    if conn == "main":
                                        last_changes += 1
                    elif op == "update":
                        if existed:
                            work[conn][key] = value
                            total[conn] += 1
                            if conn == "main":
                                last_changes = 1
                        else:
                            if conn == "main":
                                last_changes = 0
            else:
                return None

        # channel value
        if channel_mode == "changes":
            ch = last_changes
        elif channel_mode == "total_main":
            ch = total["main"]
        elif channel_mode == "total_both":
            ch = total["main"] + total["other"]
        else:
            return None
        return (ch, len(committed), sum(committed.values()))

    # Determine consistent family members from history.
    put_modes = ["ignore", "replace", "upsert"]
    triggers = [False, True]
    channel_modes = ["changes", "total_main", "total_both"]

    survivors = []
    for pm in put_modes:
        for tr in triggers:
            for cm in channel_modes:
                ok = True
                for rec in hist:
                    actions = rec.get("actions", [])
                    obs = rec.get("observed", {})
                    res = simulate(pm, tr, cm, actions)
                    if res is None:
                        ok = False
                        break
                    ch, cc, cs = res
                    if ch != obs.get("channel") or cc != obs.get("committed_count") or cs != obs.get("committed_sum"):
                        ok = False
                        break
                if ok:
                    survivors.append((pm, tr, cm))

    if not survivors:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    results = []
    for pm, tr, cm in survivors:
        res = simulate(pm, tr, cm, actions)
        if res is None:
            return {"value": None, "unresolved": True}
        ch, cc, cs = res
        if goal == "channel":
            results.append(ch)
        elif goal == "committed_count":
            results.append(cc)
        elif goal == "committed_sum":
            results.append(cs)
        else:
            return {"value": None, "unresolved": True}

    if len(set(results)) == 1:
        return {"value": results[0], "unresolved": False}
    return {"value": None, "unresolved": True}

